/**
 * External dependencies
 */
import apiFetch from '@wordpress/api-fetch';
import { __ } from '@wordpress/i18n';
import { WebsocketProvider, type WebsocketProviderOptions } from 'y-websocket';

import { createSharedWebSocketAdapter } from '@/shared-websocket';
import {
	isDevelopment,
	BLOG_ID,
	MULTIPLEXING_ENABLED,
	WEBSOCKET_PROVIDER_MAX_BACKOFF_IN_MS,
	WEBSOCKET_URL,
} from '@/utilities/config';
import { generateUUID } from '@/utilities/crypto';
import { WebSocketError, getErrorMessage } from '@/utilities/error';
import { memoizeFn } from '@/utilities/function';
import { Logger } from '@/utilities/logger';
import {
	getMaxClientsPerRoom,
	isLimitEnforced,
	isLocalClientWithinLimit,
	readPresences,
	type RoomLimitPresence,
} from '@/utilities/room-client-limit';
import { SyncConnectionStatusEmitter } from '@/utilities/sync-event-emitter';
import { getWebSocketClosePolicy, getWebSocketCloseScope } from '@/websocket-close-policy';

import type {
	ConnectionStatus,
	ProviderCreator,
	ProviderCreatorOptions,
	ProviderCreatorResult,
	ProviderEventMap,
} from '@/types/sync';

export interface WebSocketConnectionConfig {
	options?: WebsocketProviderOptions;
	serverUrl: string;
}

interface WebSocketConnectionDependencies {
	multiplexingEnabled?: boolean;
	PhysicalWebSocket?: typeof WebSocket;
	fetchToken?: ( syncObjectType: string, syncObjectId: string ) => Promise< string >;
	waitBeforeRetry?: ( delayInMs: number ) => Promise< void >;
}

const defaultResult: ProviderCreatorResult = {
	destroy: () => {},
	on: () => {},
};

/**
 * Creates a client ID generator with in-memory storage
 */
const getWpClientId = memoizeFn( (): string => generateUUID() );

const logger = new Logger( 'websocket-client' );

/**
 * Fetch a fresh authentication token from the REST API.
 */
async function fetchAuthToken( syncObjectType: string, syncObjectId: string ): Promise< string > {
	const data = await apiFetch< { token: string } >( {
		path: '/vip-rtc/v1/websocket/auth',
		method: 'POST',
		data: {
			syncObjectType,
			syncObjectId,
			wpClientId: getWpClientId(),
		},
	} );

	if ( ! data.token ) {
		throw new Error( __( 'No auth token returned', 'vip-real-time-collaboration' ) );
	}

	return data.token;
}

/**
 * Log a link to inspect the Yjs provider using Yjs inspector.
 */
function logInspectUrl( provider: WebsocketProvider ): void {
	const connectionConfig = {
		createNewDoc: false,
		room: `${ provider.roomname }?auth=${ provider.params?.auth }`,
		provider: 'y-websocket',
		url: WEBSOCKET_URL,
	};

	// The inspect URL always targets a local Yjs inspector.
	const inspectUrl = `http://localhost:5173/#/connection=${ encodeURIComponent(
		JSON.stringify( connectionConfig )
	) }`;

	logger.info( `Yjs inspector for ${ provider.roomname }: ${ inspectUrl }` );
}

/**
 * Number of consecutive failed reconnect attempts after which the provider
 * signals `backgroundRetriesFailed: true` so Gutenberg's default disconnection
 * modal becomes visible.
 */
const BACKGROUND_RETRIES_FAILED_THRESHOLD = 3;

/**
 * y-websocket emits `status: 'connected'` on raw WebSocket open before the
 * application-level handshake fully settles. Delay retry-state reset briefly
 * so server-side rejections (for example 4002 / 4003) do not immediately drop
 * the reconnect loop back to its shortest interval.
 */
const CONNECTION_STABLE_RESET_DELAY_MS = 2000;

/**
 * How long to let awareness (presence) settle after a change before deciding
 * whether the local client is over the room's connection limit. Coalesces
 * the burst of awareness updates that arrives when peers connect.
 */
const ROOM_LIMIT_SETTLE_DELAY_MS = 1500;

function getBackoffDelayInMs( attempts: number ): number {
	return Math.min( 1000 * 2 ** attempts, WEBSOCKET_PROVIDER_MAX_BACKOFF_IN_MS );
}

/**
 * Configure the websocket provider to use auth token for websocket connection.
 * Implement exponential backoff for reconnect attempts since we are opting out
 * of the built-in reconnect logic by disabling `provider.shouldConnect`.
 */
function createConnect(
	provider: WebsocketProvider,
	syncObjectType: string,
	syncObjectId: string,
	retryState: { attempts: number; eligible: boolean },
	fetchToken: ( syncObjectType: string, syncObjectId: string ) => Promise< string >,
	waitBeforeRetry: ( delayInMs: number ) => Promise< void >,
	onFatalConnectError: ( error: unknown ) => void
): () => Promise< void > {
	let hasAttemptedConnect = false;

	const connect = async (): Promise< void > => {
		if ( ! retryState.eligible ) {
			return;
		}

		if ( hasAttemptedConnect ) {
			const backoffDelayInMs = getBackoffDelayInMs( retryState.attempts );
			logger.warn(
				`Attempting to reconnect to WebSocket in ${ Math.floor( backoffDelayInMs / 1000 ) }s...`
			);
			await waitBeforeRetry( backoffDelayInMs );
			if ( ! retryState.eligible ) {
				return;
			}
		}

		hasAttemptedConnect = true;
		retryState.attempts += 1;

		let authToken: string;
		try {
			authToken = await fetchToken( syncObjectType, syncObjectId );
		} catch ( error: unknown ) {
			logger.error(
				`${ __(
					'Failed to fetch auth token and connect to WebSocket',
					'vip-real-time-collaboration'
				) }: ${ getErrorMessage( error ) }`
			);
			if ( retryState.eligible ) {
				// Keep the initial provider creation detached from a REST outage.
				void connect().catch( () => {} );
			}
			return;
		}

		if ( ! retryState.eligible ) {
			return;
		}

		try {
			provider.params = {
				auth: authToken,
			};
			provider.connect();

			// Disable provider#shouldConnect to prevent websocket from attempting to
			// reconnect before the new auth token is fetched (they are short-lived).
			// When provider.connect() runs it updates provider#shouldConnect to true.
			provider.shouldConnect = false;

			logInspectUrl( provider );
		} catch ( error: unknown ) {
			onFatalConnectError( error );
			throw error;
		}
	};

	return connect;
}

/**
 * Wire up cooperative, client-side enforcement of the per-room collaborator
 * limit (see {@link getMaxClientsPerRoom}).
 *
 * Every client reads Gutenberg's own `collaboratorInfo` awareness field for
 * each connection's join time and runs the same deterministic ranking over the
 * shared awareness state. Connections that sort past the configured limit
 * disconnect themselves; the yield is terminal (the close handler does not
 * reconnect), so a yielded user must reload to retry. We never write to
 * awareness — doing so would require registering a field equality check with
 * Gutenberg.
 *
 * This is best-effort only: simultaneous joins can briefly exceed the limit
 * before awareness settles, and a modified client can ignore the cap entirely.
 * Authoritative enforcement must live on the server.
 *
 * @param {WebsocketProvider}        provider   The room's provider.
 * @param {string}                   roomName   The sync room name.
 * @param {(exceeded: boolean)=>void} onChange  Called with whether the local client is over the limit.
 * @return {() => void} Cleanup function that detaches listeners.
 */
function setupRoomClientLimit(
	provider: WebsocketProvider,
	roomName: string,
	onChange: ( exceeded: boolean ) => void
): () => void {
	const limit = getMaxClientsPerRoom( roomName );
	if ( ! isLimitEnforced( limit ) ) {
		return () => {};
	}

	const { awareness } = provider;

	// Ranking uses Gutenberg's `collaboratorInfo.enteredAt`, which is each
	// client's own wall clock, so first-come-first-served ordering is only as
	// accurate as the clients' clocks agree. Skew can change who keeps the slot
	// when two users join close together; the `clientId` tie-break keeps the
	// ranking deterministic but not skew-proof. This is an accepted tradeoff for
	// best-effort, client-side enforcement — authoritative ordering would require
	// the server to stamp join order (see VIP-3150).
	let settleTimer: ReturnType< typeof setTimeout > | null = null;

	const evaluate = (): void => {
		settleTimer = null;

		// Only act while connected. On disconnect, awareness collapses to just our
		// own state and would otherwise read as within the limit.
		if ( ! provider.wsconnected ) {
			return;
		}

		const presences: RoomLimitPresence[] = readPresences( awareness.getStates() );
		const withinLimit = isLocalClientWithinLimit( presences, awareness.clientID, limit );

		onChange( ! withinLimit );

		if ( ! withinLimit ) {
			logger.warn(
				`Room ${ roomName } is at its connection limit (${ limit }); disconnecting this client.`
			);
			provider.disconnect();
		}
	};

	const scheduleEvaluate = (): void => {
		if ( settleTimer !== null ) {
			clearTimeout( settleTimer );
		}
		settleTimer = setTimeout( evaluate, ROOM_LIMIT_SETTLE_DELAY_MS );
	};

	// Re-evaluate whenever the socket (re)connects, not only on awareness change.
	// Awareness state may already be present, or have arrived before the socket
	// finished opening, in which case `evaluate` would otherwise have bailed on
	// `! provider.wsconnected` with nothing left to re-trigger it.
	const onStatus = ( event: { status?: string } ): void => {
		if ( event?.status === 'connected' ) {
			scheduleEvaluate();
		}
	};

	awareness.on( 'change', scheduleEvaluate );
	provider.on( 'status', onStatus );

	return () => {
		if ( settleTimer !== null ) {
			clearTimeout( settleTimer );
		}
		awareness.off( 'change', scheduleEvaluate );
		provider.off( 'status', onStatus );
	};
}

/**
 * Function that creates a new WebSocket Connection.
 *
 * @param {string} serverUrl The WebSocket server URL.
 * @param {WebSocketConnectionDependencies} dependencies Optional test overrides.
 * @return {ProviderCreator} A function that connects a Y.Doc to a WebSocket server.
 */
export function createWebSocketConnection(
	serverUrl: string,
	dependencies: WebSocketConnectionDependencies = {}
): ProviderCreator {
	const multiplexingEnabled = dependencies.multiplexingEnabled ?? MULTIPLEXING_ENABLED;
	const fetchToken = dependencies.fetchToken ?? fetchAuthToken;
	const waitBeforeRetry =
		dependencies.waitBeforeRetry ??
		( ( delayInMs: number ) => new Promise( resolve => setTimeout( resolve, delayInMs ) ) );
	const providerOptions: WebsocketProviderOptions = {
		/**
		 * Disable automatic connection to prevent websocket from attempting to connect
		 * before the auth token is fetched.
		 */
		connect: false,
	};

	if ( multiplexingEnabled ) {
		providerOptions.WebSocketPolyfill = createSharedWebSocketAdapter(
			serverUrl,
			dependencies.PhysicalWebSocket
		);
	} else if ( dependencies.PhysicalWebSocket ) {
		// Tests inject a socket here. Production leaves it unset so y-websocket
		// uses the native WebSocket for the legacy per-room transport.
		providerOptions.WebSocketPolyfill = dependencies.PhysicalWebSocket;
	}

	const config: WebSocketConnectionConfig = {
		serverUrl,
		options: providerOptions,
	};

	return async function ( {
		awareness,
		objectType,
		objectId,
		ydoc,
	}: ProviderCreatorOptions ): Promise< ProviderCreatorResult > {
		try {
			// For now, we only support collections and traditional post types.
			const isUnsupportedObjectType =
				null !== objectId &&
				( ! objectType.startsWith( 'postType/' ) || ! parseInt( objectId, 10 ) );

			if ( isUnsupportedObjectType ) {
				logger.debug( 'WebSocket connection skipped for unsupported object', {
					objectType,
					objectId,
				} );
				return defaultResult;
			}

			/**
			 * Some entities like posts aren't unique across all sites in a multisite setup.
			 * To avoid conflicts, we add the blog ID to the room name.
			 *
			 * This might not be desired for entities like sites which are unique across the
			 * multisite. We don't sync entities like those yet. When we do, we'll need to revisit
			 * adding the blog ID to the room name as that won't be needed.
			 */
			const roomName = `site-${ BLOG_ID ?? 1 }/${ objectType }-${ objectId ?? 'collection' }`;
			const options = {
				...config.options,
				awareness,
			};
			const provider = new WebsocketProvider( config.serverUrl, roomName, ydoc, options );
			const retryState = { attempts: 0, eligible: true };
			let connect: () => Promise< void > = async () => {};

			// Set when this connection voluntarily yields its slot because the room
			// is over its configured connection limit (see `setupRoomClientLimit`).
			// This yield is terminal: the close handler surfaces the limit modal and
			// does NOT reconnect. Reconnecting would re-occupy the slot, re-trigger
			// the eviction, and thrash the server (manifesting as a follow-on 4002
			// connection-limit rejection).
			let roomLimitExceeded = false;

			// Create a typed event emitter for our custom sync-connection-status event.
			const syncStatusEmitter = new SyncConnectionStatusEmitter();

			const cleanupRoomClientLimit = setupRoomClientLimit( provider, roomName, exceeded => {
				roomLimitExceeded = exceeded;
			} );

			let attemptsResetTimerId: ReturnType< typeof setTimeout > | null = null;

			const handleConnectionClose = ( event: CloseEvent | null ): void => {
				const closeCode = event?.code;
				const closeScope = getWebSocketCloseScope( event );
				const closePolicy = getWebSocketClosePolicy( closeScope, closeCode, roomLimitExceeded );
				const shouldRetry = closePolicy.shouldRetry;
				if ( closeScope === 'room' ) {
					const details = {
						room: roomName,
						closeCode,
						willRetry: shouldRetry,
					};
					if ( shouldRetry ) {
						logger.warn( 'WebSocket room connection closed', details );
					} else {
						logger.error( 'WebSocket room connection closed', details );
					}
				}
				if ( ! shouldRetry ) {
					retryState.eligible = false;
				}

				// Retry-state fields drive Gutenberg's default modal (countdown
				// and threshold-based reveal). Omit them for errors handled by
				// our custom modal so the `editor.isSyncConnectionErrorHandled`
				// filter keeps Gutenberg's modal fully suppressed; emitting
				// `willAutoRetryInMs` would make `canRetry` truthy and bypass
				// the takeover check. `canManuallyRetry` is never set: the
				// default modal's Retry button calls `retrySyncConnection()`
				// which only reaches the built-in HTTP polling provider.
				const retryStateFields = closePolicy.includeRetryMetadata
					? {
							willAutoRetryInMs: getBackoffDelayInMs( retryState.attempts ),
							backgroundRetriesFailed: retryState.attempts >= BACKGROUND_RETRIES_FAILED_THRESHOLD,
					  }
					: {};

				syncStatusEmitter.emit( {
					status: 'disconnected',
					error: new WebSocketError( closePolicy.errorCode ),
					...retryStateFields,
				} );

				// A room-limit yield is terminal — do not reconnect (see above).
				if ( shouldRetry ) {
					void connect().catch( () => {} );
				}
			};

			provider.on( 'connection-close', handleConnectionClose );

			// Listen to y-websocket's status event for connecting/connected states
			const handleStatus = ( event: ConnectionStatus ): void => {
				if ( event.status === 'connected' ) {
					if ( attemptsResetTimerId !== null ) {
						clearTimeout( attemptsResetTimerId );
					}
					attemptsResetTimerId = setTimeout( () => {
						retryState.attempts = 0;
						attemptsResetTimerId = null;
					}, CONNECTION_STABLE_RESET_DELAY_MS );
				} else if ( attemptsResetTimerId !== null ) {
					clearTimeout( attemptsResetTimerId );
					attemptsResetTimerId = null;
				}

				/*
				 * Skip 'disconnected' status - handled in connection-close above to preserve error details.
				 * y-websocket emits 'connection-close' (with error code) then 'status: disconnected' (no error).
				 */
				if ( event.status !== 'disconnected' ) {
					syncStatusEmitter.emit( { status: event.status } );
				}
			};
			provider.on( 'status', handleStatus );

			let disposed = false;
			const disposeProvider = (): void => {
				if ( disposed ) {
					return;
				}
				disposed = true;
				retryState.eligible = false;
				if ( attemptsResetTimerId !== null ) {
					clearTimeout( attemptsResetTimerId );
					attemptsResetTimerId = null;
				}
				cleanupRoomClientLimit();
				provider.off( 'connection-close', handleConnectionClose );
				provider.off( 'status', handleStatus );
				syncStatusEmitter.destroy();
				provider.destroy();
			};

			connect = createConnect(
				provider,
				objectType,
				objectId ?? 'collection',
				retryState,
				fetchToken,
				waitBeforeRetry,
				error => {
					logger.critical( 'Fatal WebSocket connection failure', { error } );
					disposeProvider();
				}
			);

			// Provide some debugging functions in development mode.
			if ( isDevelopment() ) {
				// Because there are multiple providers, disconnectWebSocket() and
				// reconnectWebSocket() will be overridden by the last entity or collection
				// provider created. Call the previous function if present.

				const previousDisconnectFunction = window.VIP_RTC.debug.disconnectWebSocket;
				window.VIP_RTC.debug.disconnectWebSocket = () => {
					if ( previousDisconnectFunction ) {
						previousDisconnectFunction();
					}

					provider.disconnect();
				};

				const previousReconnectFunction = window.VIP_RTC.debug.reconnectWebSocket;
				window.VIP_RTC.debug.reconnectWebSocket = () => {
					if ( previousReconnectFunction ) {
						previousReconnectFunction();
					}

					void connect().catch( () => {} );
				};
			}

			await connect();

			return {
				destroy: disposeProvider,
				on: < K extends keyof ProviderEventMap >(
					event: K,
					callback: ( data: ProviderEventMap[ K ] ) => void
				) => {
					if ( 'status' === event ) {
						syncStatusEmitter.on( callback );
					}
				},
			};
		} catch ( err ) {
			logger.critical( 'Failed to create WebSocket connection', { error: err } );
		}

		return defaultResult;
	};
}
